CallMatchKickoffFirst <- function ()
{
	if (eventCounter == 0)
	{
		CMND_BTL_SET_MATCH_PHASE(0, 60);
		CMND_BTL_SET_PURPOSE(3, -1, true, 0, -0.40000001, 0);
		CMND_BTL_SET_PURPOSETEXT(true, "purpose_130");
		// Position 0 of team 1 and of team 0 win their clashes
		CMND_BTL_SET_FORCE_WIN(true, 0, 1, true);
		CMND_BTL_SET_FORCE_WIN(true, 0, 0, true);
		CMND_BTL_SET_MATCH_EFFECT(1, 0);
		eventCounter++;
	}
};

BtlSetting <- function ()
{
